window.RP_SESSION={"id":"S-7d1c2313491e","messages":[{"id":"RP-II-0151740","time":"2026-08-14T13:12:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아자자~! 오늘도 화이팅!","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151741","time":"2026-08-14T13:13:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스가 손을 쭉 뻗어냈습니다. 열심히 밖으로 나와 돌아다닐 겸, 그리고 오래간만에 숲 쪽을 산책도 할 겸. 편안한 표정으로 웃음을 짓고서는. 살살 이리저리 걸어다닙니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151742","time":"2026-08-14T13:14:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"최근에는 사실 예쁜 꽃을 찾아서, 압화를 만들 생각만 하느냐고 꽤나···. 바빴습니다. 이런저런 것들을 찾아보기도 하고, 사실 그냥 책을 읽지는 않았고요···. 물론 그런 책도 찾아보았으나. 요즘은 말이지요······!","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151743","time":"2026-08-14T13:14:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그냥 두꺼운 책을 찾고 있었어요.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151744","time":"2026-08-14T13:14:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"압화 해야하니까요.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151745","time":"2026-08-14T13:15:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"걱정이 전부 해결된 것은 진실인 것 같아요. 생각도 달라졌고···.\n\n그냥 이제는요.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151746","time":"2026-08-14T13:15:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"오늘을, 당장 내 눈 앞에 존재하는 시간을 즐겁게 보내고 싶어요. 다른 걸 더 생각하고 싶지는 않고.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0151747","time":"2026-08-14T14:30:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션과 델타인, 엘레나, 아치타 등등의 꼬꼬맹이들이 갑옷 녹 벗기기에 열중한 사이…","characters":[]},{"id":"RP-II-0151748","time":"2026-08-14T14:30:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"수풀 사이를 스스슥.","characters":[]},{"id":"RP-II-0151749","time":"2026-08-14T14:31:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이어서 뾰족한 뿔이 스윽…","characters":[]},{"id":"RP-II-0151750","time":"2026-08-14T14:41:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"@마리우스 와 눈이 마주쳤다!","characters":[]},{"id":"RP-II-0151751","time":"2026-08-14T14:51:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"(눈동자)","characters":[]},{"id":"RP-II-0151752","time":"2026-08-14T15:58:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"눈이 마주치기만… 했다.","characters":[]},{"id":"RP-II-0151753","time":"2026-08-14T15:58:00+09:00","room":"RP II","name":"미상 인물 / 서술","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0151754","time":"2026-08-14T15:58:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
